/**
 * Название эпизода на языке интерфейса: перевод → для ru/uk без перевода — русское название → null
 * (карта пишет «Эпизод N», как раньше). Старый learningV2SessionTitleV1 не меняется.
 */
export function learningV2SessionTitleForLocaleV1(lessonOrdinal: number, sessionOrdinal: number, locale: string): string | null {
  if (locale === 'ru') return learningV2SessionTitleV1(lessonOrdinal, sessionOrdinal);
  const row = LEARNING_V2_SESSION_TITLES_I18N_V1[`${lessonOrdinal}.${sessionOrdinal}`];
  const translated = row?.[locale as TitleLocale];
  if (translated) return translated;
  return locale === 'uk' ? learningV2SessionTitleV1(lessonOrdinal, sessionOrdinal) : null;
}
